-- Marketing module: additive only. No personal data is stored in these tables.
CREATE TABLE marketing_settings (activity_id text PRIMARY KEY REFERENCES activities(id), settings jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO marketing_settings(activity_id) VALUES('bitg');
CREATE TABLE marketing_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id text NOT NULL REFERENCES activities(id), job text NOT NULL CHECK(job IN ('research','plan')), trigger text NOT NULL CHECK(trigger IN ('manual','schedule')), status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','failed')), started_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz NOT NULL, finished_at timestamptz, stats jsonb NOT NULL DEFAULT '{}', error text CHECK(length(error)<=500), cost_cents integer NOT NULL DEFAULT 0 CHECK(cost_cents>=0));
-- At most one active run per job; an expired lease is marked failed before a restart.
CREATE UNIQUE INDEX marketing_runs_one_active ON marketing_runs(activity_id,job) WHERE status='running';
CREATE INDEX marketing_runs_started_idx ON marketing_runs(activity_id,started_at DESC);
CREATE TABLE marketing_research_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id text NOT NULL REFERENCES activities(id), source text NOT NULL CHECK(length(source) BETWEEN 2 AND 80), kind text NOT NULL CHECK(kind IN ('trend','evergreen','question','mistake','seasonal','competitor','local','performance')), title text NOT NULL CHECK(length(title) BETWEEN 3 AND 200), summary text NOT NULL CHECK(length(summary)<=2000), url text CHECK(url IS NULL OR (url ~ '^https://' AND length(url)<=500)), ref text NOT NULL CHECK(length(ref)<=120), fingerprint text NOT NULL CHECK(fingerprint ~ '^[0-9a-f]{64}$'), is_demo boolean NOT NULL DEFAULT false, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, UNIQUE(activity_id,fingerprint));
CREATE INDEX marketing_research_expiry_idx ON marketing_research_items(expires_at);
CREATE TABLE marketing_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id text NOT NULL REFERENCES activities(id), period date NOT NULL CHECK(extract(day FROM period)=1), fingerprint text NOT NULL CHECK(fingerprint ~ '^[0-9a-f]{64}$'), title text NOT NULL CHECK(length(title) BETWEEN 3 AND 200), description text NOT NULL CHECK(length(description)<=2000), audience text NOT NULL CHECK(length(audience)<=300), channel text NOT NULL, category text NOT NULL, relevance smallint NOT NULL CHECK(relevance BETWEEN 1 AND 5), impact smallint NOT NULL CHECK(impact BETWEEN 1 AND 5), feasibility smallint NOT NULL CHECK(feasibility BETWEEN 1 AND 5), cost_level smallint NOT NULL CHECK(cost_level BETWEEN 1 AND 5), score smallint NOT NULL CHECK(score BETWEEN 1 AND 100), rationale jsonb NOT NULL DEFAULT '[]', effort_minutes integer NOT NULL CHECK(effort_minutes BETWEEN 0 AND 6000), cost_min_eur integer NOT NULL DEFAULT 0 CHECK(cost_min_eur>=0), cost_max_eur integer NOT NULL DEFAULT 0 CHECK(cost_max_eur>=cost_min_eur), expected_impact jsonb NOT NULL DEFAULT '{}', best_moment text CHECK(length(best_moment)<=300), action text NOT NULL CHECK(length(action)<=2000), brief jsonb NOT NULL DEFAULT '{}', source text NOT NULL CHECK(length(source)<=80), is_demo boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','planned','dismissed','done')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(activity_id,period,fingerprint));
CREATE INDEX marketing_opportunities_period_idx ON marketing_opportunities(activity_id,period,score DESC);
CREATE TABLE marketing_calendar_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id text NOT NULL REFERENCES activities(id), opportunity_id uuid REFERENCES marketing_opportunities(id) ON DELETE SET NULL, scheduled_for date NOT NULL, channel text NOT NULL, category text NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 3 AND 200), brief jsonb NOT NULL DEFAULT '{}', notes text CHECK(length(notes)<=4000), effort_minutes integer NOT NULL DEFAULT 0 CHECK(effort_minutes BETWEEN 0 AND 6000), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','rejected','scheduled','published')), generated_by text NOT NULL CHECK(generated_by IN ('planner','owner')), is_demo boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX marketing_calendar_date_idx ON marketing_calendar_items(activity_id,scheduled_for);
